const helmet = require('helmet');

const app = express();

app.disable('x-powered-by');
app.use(helmet({
  // Consider adjusting CSP depending on whether you serve HTML.
  contentSecurityPolicy: false, // enable and tune if you render pages
}));
```

**If behind HTTPS**, enable HSTS (only in production):

```js
